{
  "families": [
    {
      "family": "iterative",
      "ranges": [
        {"param": "data_width", "low": 11, "high": 18, "choices": null},
        {"param": "n_iter", "low": 8, "high": 20, "choices": null},
        {"param": "angle_guard", "low": -1, "high": 3, "choices": null},
        {"param": "frac_guard", "low": 0, "high": 3, "choices": null},
        {"param": "rounding", "low": null, "high": null, "choices": ["trunc", "round"]}
      ],
      "budget_share": 1.0
    ,
      "why": "Iterative shares a single datapath (one adder/subtractor, one barrel shifter) across all micro-rotations, so for any given accuracy it has the smallest LUT+FF count. The throughput constraint (>=1 MSPS) is easily satisfied because Fmax/(N+3) is far above 1 MSPS for N <= 30. Accuracy depends only on data_width, n_iter, angle_guard, frac_guard and rounding, not on the family, so any design from another family with the same accuracy parameters will have larger area and be dominated. Therefore the feasible Pareto front is expected to be entirely from iterative."
    }
  ],
  "rationale": "The spec is area-dominated: minimise LUTs+FFs subject to a loose throughput floor (1 MSPS) and a moderate accuracy bound (max_abs_err <= 2^-10). Iterative is the only family that can plausibly achieve the minimum area because it time-multiplexes the datapath. Pipelined and pipelined_m replicate datapath elements per stage, and unrolled_k replicates them per micro-rotation per cycle; all have higher area for the same accuracy. The chosen parameter ranges bracket the feasibility boundary: data_width 11 is the smallest width that can theoretically meet 2^-10 with rounding (LSB = 2^-9, half-LSB = 2^-10), while 18 gives comfortable margin for mapping higher-accuracy Pareto points. n_iter 8..20 covers the range where angle residual error transitions from dominating to negligible. angle_guard -1..3 and frac_guard 0..3 explore the trade-off between extra internal precision and area. Both rounding modes are included because rounding can save one bit of width at the same error bound. All budget is allocated to iterative to densely sample the active constraint region and the Pareto front."
}

{
  "decision": "add_family",
  "rationale": "Round 1 mapped only the `iterative` family, and the entire feasible front (13 designs, area 274..403, accuracy 10.5..14.3 bits) comes from it. Three registry families are still unexplored, so the front is a one-family slice and we cannot yet claim it is the true (area, accuracy) trade-off. Accuracy is family-independent (identical bits for the same data_width/n_iter/angle_guard/frac_guard/rounding), so the only open question is cost: whether another family reaches the same accuracy at lower luts_plus_ffs. This is plausible because the families differ structurally — `iterative` pays for barrel shifters (muxes) while `pipelined`/`pipelined_m` use fixed shifts (wiring) at the cost of more registers, so the LUT-vs-FF balance in the luts_plus_ffs proxy can flip. The constraint set is easy on throughput (best seen 18.5 MSPS vs >=1 required) and the binding constraint is accuracy (36% of evals violate 2^-10), so I focus the new families on the low-area region where the current best (274 luts_plus_ffs @ 10.5 bits) sits, plus a modest spread to keep extending the front toward the HV reference area of 1500.",
  "next_plan": {
    "families": [
      {
        "family": "unrolled_k",
        "ranges": [
          {"param": "data_width", "low": 14, "high": 20, "choices": null},
          {"param": "n_iter", "low": 10, "high": 22, "choices": null},
          {"param": "angle_guard", "low": -1, "high": 3, "choices": null},
          {"param": "frac_guard", "low": 0, "high": 3, "choices": null},
          {"param": "rounding", "low": null, "high": null, "choices": ["trunc", "round"]},
          {"param": "k", "low": 2, "high": 4, "choices": null}
        ]
      ,
      "budget_share": 0.5
      ,
      "why": "Shares one datapath across k micro-rotations/cycle; test whether fewer cycles per result can be bought without the barrel-shifter cost of the iterative family, and whether it undercuts 274 luts_plus_ffs at >=10 bits."
      },
      {
        "family": "pipelined",
        "ranges": [
          {"param": "data_width", "low": 14, "high": 20, "choices": null},
          {"param": "n_iter", "low": 10, "high": 22, "choices": null},
          {"param": "angle_guard", "low": -1, "high": 3, "choices": null},
          {"param": "frac_guard", "low": 0, "high": 3, "choices": null},
          {"param": "rounding", "low": null, "high": null, "choices": ["trunc", "round"]}
        ]
      ,
      "budget_share": 0.5
      ,
      "why": "One registered stage per micro-rotation uses fixed shifts (no barrel muxes) but many FFs; directly tests the LUT/FF trade in the luts_plus_ffs proxy against iterative at the same accuracy."
      }
    ],
    "rationale": "Keep pipelined_m in reserve for a later round; two structurally distinct families are enough to test the cost hypothesis this round while leaving budget for a final full-range front map."
  }
}

{
  "decision": "map_front",
  "next_plan": null,
  "rationale": "The feasible front spans luts_plus_ffs 274..561, only ~37% of the HV reference 1500, and accuracy_bits tops out at 17 while the registry (data_width up to 28, n_iter up to 30) clearly supports more. The explored ranges were narrow (iterative data_width 14..18 / n_iter 12..20; unrolled_k data_width 15..20 / n_iter 12..22), so the high-accuracy / higher-area region that would fill HV toward the (1500,10) reference is essentially unmapped. The min-area corner the selection rule wants is already found and constraint-feasible (iterative dw=16 n_iter=13 ag=3 fg=0 trunc: 274 LUT+FF, 10.5 bits, 12.1 MSPS, err 2^-10.47), so refining it adds little HV. pipelined_m is not worth adding: the spec needs only >=1 MSPS and pipelined's best feasible area is already 1490 (near the reference), so its 1-result/cycle throughput is wasted for a min-area objective. Best use of the remaining budget is to let code map the whole front over the full ranges of the two families actually on it (iterative, unrolled_k), seeded with the current front, to extend accuracy_bits upward and cover the luts_plus_ffs range up to the reference."
}

{
  "decision": "stop",
  "rationale": "Final round (round cap reached, 340/400 evals). The feasible front is well mapped: 255 feasible designs, 19 on the Pareto front, spanning luts_plus_ffs 256..633 and accuracy_bits 10.3..23, with hypervolume gain this round only +0.3% — the front has converged. Both constraints are comfortably satisfiable: throughput best seen 273 MSPS (0% violate, need >=1) and max_abs_err best 1.15e-07 (need <=2^-10). The selection rule (min luts_plus_ffs) is met by iterative [data_width=15 n_iter=12 angle_guard=3 frac_guard=0 rounding=round] at luts_plus_ffs=256, accuracy_bits=10.3 (max_abs_err 0.000803 <= 0.000976562), throughput 13.2 MSPS >= 1 — a valid, constraint-satisfying optimum. No further family exploration is warranted: pipelined_m is unexplored but pipelined already shows the per-cycle families cost >=1490 luts_plus_ffs, far above the 256 area optimum the spec selects for, so it cannot improve the selected design. Stopping."
  ,
  "next_plan": null
}
